export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (!state) {
      state = { tokensNum: this.capacity * this.per, lastTick: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    if (state.lastTick === null) {
      state.lastTick = tick
      return
    }
    if (tick > state.lastTick) {
      const elapsed = tick - state.lastTick
      const grown = state.tokensNum + this.refill * elapsed
      const cap = this.capacity * this.per
      state.tokensNum = grown > cap ? cap : grown
      state.lastTick = tick
    }
  }

  canAllow(key) {
    return this.#state(key).tokensNum >= this.per
  }

  record(key) {
    this.#state(key).tokensNum -= this.per
  }
}

