  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (!state) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    const threshold = tick - this.span
    state.ticks = state.ticks.filter((t) => t > threshold)
  }

  canAllow(key) {
    return BigInt(this.#state(key).ticks.length) < this.limit
  }

  record(key, tick) {
    this.#state(key).ticks.push(tick)
  }
}
