{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-Sc8VR0/src/simulate.js","content":"/**
 * Parses a limiter file and replays its events, producing either a
 * per-event log or a per-key summary. Throws a `LineError` naming the
 * offending line whenever the file fails to parse.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

const IDENT_RE = /^[A-Za-z0-9_./:-]+$/
const UINT_RE = /^(0|[1-9][0-9]*)$/

export class LineError extends Error {
  constructor(line, reason) {
    super(`error: line ${line}: ${reason}`)
    this.line = line
  }
}

function parseUint(fieldName, token, least) {
  if (UINT_RE.test(token) && BigInt(token) >= BigInt(least)) {
    return BigInt(token)
  }
  return { error: `${fieldName} must be an integer of at least ${least}` }
}

function requireUint(line, fieldName, token, least) {
  const result = parseUint(fieldName, token, least)
  if (typeof result === 'object' && 'error' in result) {
    throw new LineError(line, result.error)
  }
  return result
}

function requireIdent(line, kind, token, message) {
  if (!IDENT_RE.test(token)) {
    throw new LineError(line, `${message} ${token}`)
  }
  return token
}

/**
 * Runs a limiter file, in the given mode, and returns the text that should
 * be written to standard output.
 */
export function run(mode, input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const policies = new Map()
  const routes = []
  let firstEventSeen = false
  let lastTick = null

  const replayLines = []
  const keyStats = new Map()
  const totals = { allowed: 0n, denied: 0n }

  function statsFor(key) {
    let stats = keyStats.get(key)
    if (!stats) {
      stats = { allowed: 0n, denied: 0n }
      keyStats.set(key, stats)
    }
    return stats
  }

  function matchRoute(key) {
    let best = null
    for (const route of routes) {
      if (key.startsWith(route.prefix)) {
        if (best === null || route.prefix.length > best.prefix.length) {
          best = route
        }
      }
    }
    return best
  }

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue
    }
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket') {
      if (tokens.length !== 5) {
        throw new LineError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      }
      if (firstEventSeen) {
        throw new LineError(lineNo, 'declarations must come before the first event')
      }
      const [, name, capacityTok, refillTok, perTok] = tokens
      requireIdent(lineNo, 'name', name, 'invalid policy name')
      if (policies.has(name)) {
        throw new LineError(lineNo, `policy ${name} is declared twice`)
      }
      const capacity = requireUint(lineNo, 'capacity', capacityTok, 1)
      const refill = requireUint(lineNo, 'refill', refillTok, 0)
      const per = requireUint(lineNo, 'per', perTok, 1)
      policies.set(name, new TokenBucket(capacity, refill, per))
      continue
    }

    if (directive === 'window') {
      if (tokens.length !== 4) {
        throw new LineError(lineNo, 'expected window <name> <limit> <span>')
      }
      if (firstEventSeen) {
        throw new LineError(lineNo, 'declarations must come before the first event')
      }
      const [, name, limitTok, spanTok] = tokens
      requireIdent(lineNo, 'name', name, 'invalid policy name')
      if (policies.has(name)) {
        throw new LineError(lineNo, `policy ${name} is declared twice`)
      }
      const limit = requireUint(lineNo, 'limit', limitTok, 0)
      const span = requireUint(lineNo, 'span', spanTok, 1)
      policies.set(name, new SlidingWindow(limit, span))
      continue
    }

    if (directive === 'route') {
      if (tokens.length < 3) {
        throw new LineError(lineNo, 'expected route <prefix> <policy>...')
      }
      if (firstEventSeen) {
        throw new LineError(lineNo, 'declarations must come before the first event')
      }
      const prefix = tokens[1]
      requireIdent(lineNo, 'prefix', prefix, 'invalid route prefix')
      if (routes.some((r) => r.prefix === prefix)) {
        throw new LineError(lineNo, `prefix ${prefix} is routed twice`)
      }
      const policyNames = tokens.slice(2)
      for (const name of policyNames) {
        if (!policies.has(name)) {
          throw new LineError(lineNo, `unknown policy ${name}`)
        }
      }
      routes.push({ prefix, policyNames })
      continue
    }

    if (directive === 'event') {
      if (tokens.length !== 3) {
        throw new LineError(lineNo, 'expected event <tick> <key>')
      }
      firstEventSeen = true
      const [, tickTok, key] = tokens
      const tick = requireUint(lineNo, 'tick', tickTok, 0)
      if (lastTick !== null && tick < lastTick) {
        throw new LineError(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      requireIdent(lineNo, 'key', key, 'invalid key')

      const route = matchRoute(key)
      const policyNames = route ? route.policyNames : []
      const active = policyNames.map((name) => policies.get(name))

      for (const policy of active) {
        policy.advance(key, tick)
      }

      let deniedBy = null
      for (let p = 0; p < active.length; p++) {
        if (!active[p].canAllow(key)) {
          deniedBy = policyNames[p]
          break
        }
      }

      const stats = statsFor(key)
      if (deniedBy === null) {
        for (const policy of active) {
          policy.record(key, tick)
        }
        stats.allowed += 1n
        totals.allowed += 1n
        replayLines.push(`${tick} ${key} allow`)
      } else {
        stats.denied += 1n
        totals.denied += 1n
        replayLines.push(`${tick} ${key} deny ${deniedBy}`)
      }
      continue
    }

    throw new LineError(lineNo, `unknown directive ${directive}`)
  }

  if (mode === 'replay') {
    return replayLines.length === 0 ? '' : replayLines.join('\n') + '\n'
  }

  const summaryLines = []
  for (const key of Array.from(keyStats.keys()).sort()) {
    const stats = keyStats.get(key)
    summaryLines.push(`${key} allowed=${stats.allowed} denied=${stats.denied}`)
  }
  summaryLines.push(`total allowed=${totals.allowed} denied=${totals.denied}`)
  return summaryLines.join('\n') + '\n'
}
"}

